/// Returns the index of the minimum element in the slice `a`,
/// considering only elements from index `i` up to the end of the slice.
/// 
/// # Panics
/// 
/// Panics if `i >= a.len()`.
fn look_for_min(a: &[i64], i: usize) -> usize {
    assert!(i < a.len(), "start index out of bounds");
    let mut min_index = i;
    for j in (i + 1)..a.len() {
        if a[j] < a[min_index] {
            min_index = j;
        }
    }
    min_index
}

